1	/**
2	 * routes/plugins.ts
3	 *
4	 * CF-native handlers for:
5	 *   GET /api/plugins
6	 *   GET /api/plugins/ui-contributions
7	 *   GET /api/plugins/examples
8	 *   POST /api/plugins/install
9	 *
10	 * The server-side pluginRoutes() relies on an in-process plugin registry
11	 * (worker processes, SSE, child_process) that does not exist in a CF Worker.
12	 * These handlers derive the same data from the `plugins` DB table, which is
13	 * populated at install time and is always available via Hyperdrive.
14	 *
15	 * install / examples notes:
16	 *   Plugin installation requires npm access and is delegated to the sidecar
17	 *   companion server (SidecarContainer DO or SIDECAR_URL env var).
18	 *   Examples are returned with localPath = packageName so the UI issues an
19	 *   npm install rather than a local-filesystem install.
20	 *
21	 * Auth: requires an authenticated actor (board or agent). Unauthenticated
22	 * requests receive 401.
23	 */
24	
25	import type { Hono } from "hono";
26	import { asc, ne } from "drizzle-orm";
27	import { plugins } from "@paperclipai/db";
28	import { getPluginUiContributionMetadata } from "../../../../../server/src/services/plugin-loader.js";
29	import { createHyperdriveDb } from "../../db/hyperdrive.js";
30	import { resolveActorFromRequest } from "../../auth/resolve-actor.js";
31	import { resolveDeploymentMode } from "../env.js";
32	import type { Env } from "../env.js";
33	
34	
35	/** Proxy a request to the sidecar companion server. */
36	async function proxySidecar(env: Env, path: string, req: Request): Promise<Response> {
37	  if (env.SIDECAR_SERVICE) {
38	    const id = env.SIDECAR_SERVICE.idFromName("sidecar");
39	    const stub = env.SIDECAR_SERVICE.get(id);
40	    return stub.fetch(`http://sidecar${path}`, {
41	      method: req.method,
42	      headers: req.headers,
43	      body: req.body,
44	    });
45	  }
46	  const baseUrl = env.SIDECAR_URL;
47	  if (!baseUrl) {
48	    return Response.json(
49	      { error: "Plugin install not available: configure SIDECAR_URL or SIDECAR_SERVICE" },
50	      { status: 503 },
51	    );
52	  }
53	  const headers = new Headers(req.headers);
54	  if (env.SIDECAR_API_KEY) headers.set("Authorization", `Bearer ${env.SIDECAR_API_KEY}`);
55	  return fetch(`${baseUrl}${path}`, { method: req.method, headers, body: req.body });
56	}
57	
58	export function registerPluginRoutes(app: Hono<{ Bindings: Env }>): void {
59	  // -------------------------------------------------------------------------
60	  // GET /api/plugins — list installed plugins from DB (registry state comes
61	  // from manifestJson stored at install time; worker processes not available)
62	  // -------------------------------------------------------------------------
63	  app.get("/api/plugins", async (c) => {
64	    const db = createHyperdriveDb(c.env.HYPERDRIVE);
65	    const actor = await resolveActorFromRequest(c.req.raw, db, {
66	      deploymentMode: resolveDeploymentMode(c.env),
67	    });
68	    if (!actor) return c.json({ error: "Unauthorized" }, 401);
69	
70	    const rows = await db
71	      .select()
72	      .from(plugins)
73	      .where(ne(plugins.status, "uninstalled"))
74	      .orderBy(asc(plugins.installOrder));
75	    return c.json(rows);
76	  });
77	
78	  // -------------------------------------------------------------------------
79	  // GET /api/plugins/ui-contributions — derive UI contribution metadata from
80	  // manifestJson stored in the DB (no running plugin process needed).
81	  // Must be registered before /api/plugins so Hono matches it first.
82	  // -------------------------------------------------------------------------
83	  app.get("/api/plugins/ui-contributions", async (c) => {
84	    const db = createHyperdriveDb(c.env.HYPERDRIVE);
85	    const actor = await resolveActorFromRequest(c.req.raw, db, {
86	      deploymentMode: resolveDeploymentMode(c.env),
87	    });
88	    if (!actor) return c.json({ error: "Unauthorized" }, 401);
89	
90	    const rows = await db
91	      .select()
92	      .from(plugins)
93	      .where(ne(plugins.status, "uninstalled"))
94	      .orderBy(asc(plugins.installOrder));
95	
96	    const contributions = rows.flatMap((plugin) => {
97	      const manifest = plugin.manifestJson;
98	      if (!manifest) return [];
99	      const uiMetadata = getPluginUiContributionMetadata(manifest);
100	      if (!uiMetadata) return [];
101	      return [{
102	        pluginId: plugin.id,
103	        pluginKey: plugin.pluginKey,
104	        displayName: manifest.displayName,
105	        version: plugin.version,
106	        updatedAt: plugin.updatedAt.toISOString(),
107	        uiEntryFile: uiMetadata.uiEntryFile,
108	        slots: uiMetadata.slots,
109	        launchers: uiMetadata.launchers,
110	      }];
111	    });
112	    return c.json(contributions);
113	  });
114	
115	  // -------------------------------------------------------------------------
116	  // GET /api/plugins/examples — proxy to sidecar.
117	  // The sidecar runs the server's listBundledPluginExamples() which checks
118	  // whether local monorepo paths exist and returns them with absolute paths.
119	  // In local dev the monorepo IS present so examples appear; in production
120	  // the sidecar container has a different filesystem and returns [].
121	  // -------------------------------------------------------------------------
122	  app.get("/api/plugins/examples", async (c) => {
123	    const db = createHyperdriveDb(c.env.HYPERDRIVE);
124	    const actor = await resolveActorFromRequest(c.req.raw, db, {
125	      deploymentMode: resolveDeploymentMode(c.env),
126	    });
127	    if (!actor) return c.json({ error: "Unauthorized" }, 401);
128	
129	    try {
130	      const resp = await proxySidecar(c.env, "/api/plugins/examples", c.req.raw);
131	      if (!resp.ok) return c.json([]);
132	      return new Response(resp.body, { status: resp.status, headers: { "Content-Type": "application/json" } });
133	    } catch {
134	      // Sidecar unreachable (not running locally) — return empty list.
135	      return c.json([]);
136	    }
137	  });
138	
139	  // -------------------------------------------------------------------------
140	  // POST /api/plugins/install — delegate to sidecar (needs npm + filesystem).
141	  // The sidecar installs the package, registers it in the DB, and returns the
142	  // plugin record. localPath values equal to a package name are treated as
143	  // npm installs by the sidecar's install handler.
144	  // -------------------------------------------------------------------------
145	  app.post("/api/plugins/install", async (c) => {
146	    const db = createHyperdriveDb(c.env.HYPERDRIVE);
147	    const actor = await resolveActorFromRequest(c.req.raw, db, {
148	      deploymentMode: resolveDeploymentMode(c.env),
149	    });
150	    if (!actor) return c.json({ error: "Unauthorized" }, 401);
151	
152	    // CF has no local filesystem, so isLocalPath is never meaningful here.
153	    // If the UI sent isLocalPath: true with an npm package name (e.g. from
154	    // the examples list), rewrite the body to use npm install semantics.
155	    const body = await c.req.json<{ packageName?: string; version?: string; isLocalPath?: boolean }>();
156	    const isNpmPackage = !body.isLocalPath || !body.packageName?.startsWith("/");
157	    const rewritten = isNpmPackage
158	      ? { packageName: body.packageName, version: body.version, isLocalPath: false }
159	      : body;
160	
161	    try {
162	      const resp = await proxySidecar(c.env, "/api/plugins/install",
163	        new Request(c.req.url, {
164	          method: "POST",
165	          headers: { "Content-Type": "application/json" },
166	          body: JSON.stringify(rewritten),
167	        }),
168	      );
169	      return new Response(resp.body, { status: resp.status, headers: { "Content-Type": "application/json" } });
170	    } catch {
171	      return c.json(
172	        { error: "Plugin install requires the Node.js server to be running (pnpm dev or bun run dev)" },
173	        503,
174	      );
175	    }
176	  });
177	}
